        "flavor": "作为知名的形象被众人知晓，传扬，最终化作了实体。就如同传说中的一样，她暴躁，疯狂，迅捷，而且直截了当。这种性格自然会引来麻烦，但是她身边的猎犬却在警告着其他人。她在心中一直隐藏着对某位侦探的憧憬，所以她的行事风格偶尔也会有点变化呢。",
