        "flavor": "无论何时总是慢悠悠地行走，心平气和地感受这一切，这就是盘龙。虽然看起来像是个成熟的大姐姐，却总是有不成熟的发言，偶尔也会做出一点犯迷糊的举动。总的来说是一个挺让人担心的人呢~听说她还有一个妹妹，是她经常提起的人，不知道能不能有机会见到呢？",
        "firstSightDialogue": "今天的风也如此安宁，让人舒——呀！诶嘿嘿，我没事的，只是不小心摔倒了而已。",
