        "flavor": "是天命三大氏族之一沙尼亚特家族的家主，也是天命的圣女，更是天命组织当世仅有的几位S级女武神之一。在新生篇中担任圣芙蕾雅学园的学园长一职，负责培养从各地挑选的女武神候补。她宠爱着自己唯一的女儿琪亚娜，与天命的主教德丽莎亲如姐妹，对待所有人都是一副亲切的面容。但她也背负着天命的重任，知晓着天命的许多隐秘。",
