        "flavor": "丰饶女神之女。#n由于被赋予的神性会令身边的生灵陷入疯狂，以致对其产生不可遏制的杀意。无奈之下，丰饶女神只好将她托付给其姑母哈迪斯抚养。#n冥府中虽然没有性命之忧，但也令普西芬妮失去了和他人建立关系的机会。#n除了姑母的教导外，普西芬妮的大部分知识都是来自在冥府中游荡的鬼魂。从这些鬼魂身上，普西芬妮得到了许多知识，包括从古至今的各种阴谋诡计。",
