        "flavor": "塔纳托斯喜欢谈论生死，就好像在谈论一件平淡无奇的事情一样。如今的她没有呼吸、心跳和体温。她自称自己无时无刻不在死亡，无时无刻不在诞生。#n塔纳托斯曾是弑神的兵器，有着只要被击中就会死的可怕威力。据说，她用那把巨大的弑神之枪，开启了一个全新的宇宙。",
