        "flavor": "在鬼怪横行的夜晚，在主人疲于应付熊孩子们的时刻，怪盗张开漆黑的双翼，潜入古堡深处，偷走最珍贵的宝物……#n对瓦雷弗尔来说，这一套玩法早就过时了。只要在队伍里暗中观察，就能盗取无数的秘密：平时文静的假正经，可能套着南瓜头大喊大叫；平时疯狂的小鬼，也会乖巧地讨要糖果。#n都什么年代了，还当传统怪盗？",
