        "flavor": "她履血而来，所历之途足迹永铭。#n她呼啸而至，所到之处倏然黯淡。#n她降下夜幕，她开启门扉。#n她谦辞卑礼，她吐故纳新。#n她说：#n“欢迎来到神曲主题公园，远方的游魂。我是万圣之夜的引导者，神曲。”",
