        "flavor": "自西元3世纪的那次【崩坏】发生以来，卡斯兰娜家族就成为了“被选中之人”，秉承祖训，卡斯兰娜家族低调隐匿于世，深入的探寻着【崩坏】的源起，并藉由此来发觉世界之奥义。 琪亚娜是卡斯兰娜家族第69世传人，其父为卡斯兰娜家族精英，年轻时与另一“被选中之人”氏族名门之女结婚诞下琪亚娜。然而，这场政治婚姻最终在琪亚娜十岁时破裂。琪亚娜 12岁那年，父亲携年幼的她只身来到极东之地，调查被视作疑似崩坏前兆事件的“地铁沙林恐怖事件”。琪亚娜 14岁时，父亲将家学之奥义尽数传于琪亚娜，随后消失在了众人的视线中，只留下一句“我去探寻崩坏的本源了”。",
